#!/usr/bin/env bash
set -euo pipefail

REPO_ROOT=$(git rev-parse --show-toplevel)
HOOKS_DIR="$REPO_ROOT/.git/hooks"
MARKER="# alex-pre-commit-steps-check"
REFTXN_MARKER="# alex-protected-ref-transaction"

mkdir -p "$HOOKS_DIR"

TARGET="$HOOKS_DIR/pre-commit"

if [ -f "$TARGET" ] && ! grep -q "$MARKER" "$TARGET" 2>/dev/null; then
  BACKUP="$TARGET.pre-alex-$(date +%Y%m%d%H%M%S)"
  cp "$TARGET" "$BACKUP"
  echo "Backed up existing pre-commit → $BACKUP"
fi

cat > "$TARGET" <<'HOOK'
#!/usr/bin/env bash
# alex-pre-commit-steps-check
# Auto-generated by scripts/install-git-hooks.sh — safe to regenerate.
# Blocks commits that break _requirements/00-canonical/STEPS.json schema OR leave
# the canonical step-table docs drifted from STEPS.json. ALSO runs the check-lib
# fast-feedback pass (Seam D consumer b) — NON-AUTHORITATIVE,
# bypassable via --no-verify; the real integration gate is trusted-controller.js
# (Seam B) fenced by the reference-transaction hook (Seam E), never this file.
set -e

REPO_ROOT=$(git rev-parse --show-toplevel)
SCRIPT="$REPO_ROOT/scripts/hooks/pre-commit-steps-check.js"
CHECKLIB_SCRIPT="$REPO_ROOT/scripts/hooks/pre-commit-check-lib.js"

# Prefer node from PATH; give a clear error if absent.
if ! command -v node >/dev/null 2>&1; then
  echo "pre-commit: node not found on PATH — cannot validate STEPS.json" >&2
  exit 1
fi

if [ -f "$SCRIPT" ]; then
  node "$SCRIPT"
else
  # If the validator is missing, don't block — warn and let the commit through.
  # (A fresh clone without scripts/ checked out should not be strangled.)
  echo "pre-commit: $SCRIPT missing — skipping steps check" >&2
fi

if [ -f "$CHECKLIB_SCRIPT" ]; then
  node "$CHECKLIB_SCRIPT"
else
  echo "pre-commit: $CHECKLIB_SCRIPT missing — skipping check-lib fast feedback" >&2
fi
HOOK

chmod +x "$TARGET"
echo "Installed pre-commit → $TARGET"
echo "It runs node $REPO_ROOT/scripts/hooks/pre-commit-steps-check.js + pre-commit-check-lib.js"

CMSG_MARKER="# alex-change-trailer-commit-msg"
CMSG_TARGET="$HOOKS_DIR/commit-msg"

if [ -f "$CMSG_TARGET" ] && ! grep -q "$CMSG_MARKER" "$CMSG_TARGET" 2>/dev/null; then
  BACKUP="$CMSG_TARGET.pre-alex-$(date +%Y%m%d%H%M%S)"
  cp "$CMSG_TARGET" "$BACKUP"
  echo "Backed up existing commit-msg → $BACKUP"
fi

cat > "$CMSG_TARGET" <<'HOOK'
#!/usr/bin/env bash
# alex-change-trailer-commit-msg
# Auto-generated by scripts/install-git-hooks.sh — safe to regenerate.
# Validates the Change/Blast/Risks trailer on the commit message while a sprint is active.
set -e

REPO_ROOT=$(git rev-parse --show-toplevel)
SCRIPT="$REPO_ROOT/scripts/checks/change-trailer.js"

if ! command -v node >/dev/null 2>&1; then
  echo "commit-msg: node not found on PATH — skipping change-trailer check" >&2
  exit 0
fi
if [ ! -f "$SCRIPT" ]; then
  # An older worktree checkout that lacks the validator must not be strangled.
  echo "commit-msg: $SCRIPT missing — skipping change-trailer check" >&2
  exit 0
fi

set +e
node "$SCRIPT" validate --file "$1" --if-sprint-active --git-generated-ok --hook --root "$REPO_ROOT"
rc=$?
set -e
# Fail CLOSED on ANY non-zero, not just the validator's deliberate
# "block" (exit 3). A crash (SyntaxError, uncaught throw -> node's own exit 1, or this script's
# usage/internal-error exit 2) must never read as "not blocking" — otherwise a hostile commit message
# crafted to crash the validator would pass the one authoritative enforcement
# point. The PreToolUse guard (scripts/hooks/change-trailer-guard.js) is the DELIBERATE fail-OPEN
# half of this policy (an agent's own tool-call pipeline must never wedge on a bug in this
# validator mid-session); THIS hook is the authoritative, git-enforced gate for every commit
# (including a commit made outside the agent harness the PreToolUse guard never sees), so it is the one that
# must fail closed. Kill switch: MC_CHANGE_TRAILER=off short-circuits the validator to
# exit 0 before this logic ever runs (see "validate" --hook contract above).
if [ "$rc" -ne 0 ]; then
  if [ "$rc" -ne 3 ]; then
    echo "commit-msg: change-trailer check errored (exit $rc) — BLOCKING (fail-closed)" >&2
  fi
  exit 1
fi
exit 0
HOOK

chmod +x "$CMSG_TARGET"
echo "Installed commit-msg → $CMSG_TARGET"
echo "It runs node $REPO_ROOT/scripts/checks/change-trailer.js validate (change-classification trailer)"

REFTXN_TARGET="$HOOKS_DIR/reference-transaction"

if [ -f "$REFTXN_TARGET" ] && ! grep -q "$REFTXN_MARKER" "$REFTXN_TARGET" 2>/dev/null; then
  BACKUP="$REFTXN_TARGET.pre-alex-$(date +%Y%m%d%H%M%S)"
  cp "$REFTXN_TARGET" "$BACKUP"
  echo "Backed up existing reference-transaction → $BACKUP"
fi

cat > "$REFTXN_TARGET" <<'HOOK'
#!/usr/bin/env bash
# alex-protected-ref-transaction
# Auto-generated by scripts/install-git-hooks.sh — safe to regenerate.
# Seam E: the sole-route MECHANISM for refs/heads/main. Probe-confirmed
# to fire on every
# write surface (commit, update-ref, fast-forward, non-ff merge) and to ABORT the
# transaction on a non-zero exit in the 'prepared' phase — and NOT bypassed by
# --no-verify. Requires the current trusted-controller fencing token (set ONLY around
# trusted-controller.js's own writes: commitIntegration and its fenced ref updater); absent/invalid ->
# refused (git aborts the write). Outside the fence's promise, because each needs local shell access
# and intent: a core.hooksPath redirect, hook deletion, a direct .git/refs/** filesystem write, and
# forging the fencing token.
set -e

# Resolve the verifier via the COMMON git dir (shared across ALL worktrees), NOT the active
# worktree toplevel. Worktrees share this hook (common .git/hooks) but each has its own toplevel; a
# worktree checked out at an older commit can lack scripts/hooks/protected-ref-transaction.js, so resolving from
# "git rev-parse --show-toplevel" and exiting 0 on a missing script would SILENTLY SKIP the fence for a
# refs/heads/main write issued from that cwd. The common git dir points at the canonical checkout that installed it.
REPO_ROOT_COMMON=$(cd -- "$(git rev-parse --git-common-dir 2>/dev/null)" 2>/dev/null && pwd)
REPO_ROOT=$(dirname -- "$REPO_ROOT_COMMON")
SCRIPT="$REPO_ROOT/scripts/hooks/protected-ref-transaction.js"

# reference-transaction feeds old/new/ref lines on stdin -- a SINGLE-READ stream. Buffer it once so
# we can both (a) decide protected-vs-not when the verifier is unavailable and (b) re-feed it below.
STDIN_BUF=$(cat)
touches_protected() {
  printf '%s\n' "$STDIN_BUF" | grep -qE '(^|[[:space:]])refs/heads/main([[:space:]]|$)'
}

if [ ! -f "$SCRIPT" ] || ! command -v node >/dev/null 2>&1; then
  # Verifier unavailable (missing script -- an older or bare checkout -- or no node on PATH).
  # FAIL CLOSED for a protected ref; graceful-skip ONLY for non-protected (a bare clone must not
  # strangle non-main writes -- the honest ceiling stays honest for the non-protected case only).
  if touches_protected; then
    echo "reference-transaction: verifier unavailable AND a protected ref (refs/heads/main) touched -- REFUSING (fail-closed: without the verifier the fencing token cannot be checked, so the write is refused instead of let through)" >&2
    exit 1
  fi
  echo "reference-transaction: verifier unavailable (no protected ref touched) -- skipping" >&2
  exit 0
fi

# Re-feed the buffered stdin to the verifier (the stream was consumed above). node's exit is the hook
# exit; a non-zero in the 'prepared' phase ABORTS the write.
printf '%s\n' "$STDIN_BUF" | node "$SCRIPT" "$@"
HOOK

chmod +x "$REFTXN_TARGET"
echo "Installed reference-transaction → $REFTXN_TARGET"
echo "It runs node $REPO_ROOT/scripts/hooks/protected-ref-transaction.js (Seam E)"
